/// Characters exactly one language of the set writes, derived from the same
/// dev text as [`TABLES`] — see `short_lang_bench.derive_exclusive`. `ç` is
/// not French here and `ø` is not Danish, because Turkish, Portuguese and
/// Norwegian have them: shared is not exclusive, whatever it looks like.
pub const EXCLUSIVE: &[(&str, &str)] = &[
    ("cs", "ýčěřšůž"),
    ("es", "ñ"),
    ("pl", "ąćęłńśż"),
    ("pt", "ãõ"),
    ("tr", "ğış"),
];

/// Languages the diacritic stage may answer with (FINDINGS §21's gate).
pub const DIACRITIC_SHIP: &[&str] = &["cs", "es", "pl", "pt", "tr"];

/// The two-word floor both new stages apply, and the margin coefficients
/// the trigram stage decides with: `A + B / sqrt(trigrams)`. Duplicated
/// into `lang.rs` as typed constants and asserted equal by a test there —
/// these are the values FINDINGS §21's table was measured at.
pub const MIN_WORDS: usize = 2;
pub const MARGIN_A: f32 = 0.1;
pub const MARGIN_B: f32 = 1.3;
pub const MARGIN_DEEN_A: f32 = 0.14;
pub const MARGIN_DEEN_B: f32 = 1.8;

/// Languages the trigram stage may answer with. Everything else in
